typedef float vm_num_t;

extern "C" float sqrtf(float);
extern void error(const char *);

class vm_stack
{
public:
  int salloc;
  char *buffer;
  char *SP;
private:
  void *my_thread;
protected:
  void move_SP(int n)
  {
    SP += n;
  }
public:
  char *get_SP() const { return SP; }
  void pop(int n) { move_SP(-n); }
  bool push(const char *src, int n);
};

template<class T> class vector3d_t
{
public:
  T x;
  T y;
  T z;

  inline T xz_length() const { return (T)sqrtf(x*x + z*z); }
};

typedef vector3d_t<float> vector3d;

class script_library_class
{
public:
  class function
  {
  public:
    enum entry_t { FIRST_ENTRY };
  };
};

class slf_vector3d_xz_norm_t : public script_library_class::function
{
public:
  struct parms_t
  {
    vector3d me;
  };

  virtual bool operator()(vm_stack& stack,entry_t entry)
  {
    stack.pop(sizeof(parms_t));
    parms_t* parms = (parms_t*)stack.get_SP();
    vm_num_t result = parms->me.xz_length();
    if (!stack.push((char*)&result,sizeof(result)) )
      error( "script stack overflow" );
    return true;
  }
};
